def validate_path(relative):

    if not isinstance(relative, str) or not relative or '\\' in relative:
        raise ValueError('invalid_package_path')
    path = PurePosixPath(relative)
    if path.is_absolute() or path.as_posix() != relative or any(p in ('.', '..', '') for p in path.parts):
        raise ValueError('invalid_package_path')
    for part in path.parts:
        lower = part.lower()
        if lower in BANNED or lower.startswith('.') or lower.endswith(('.pem', '.key', '.p12', '.log', '.env')) or lower.startswith('.env'):
            raise ValueError('forbidden_package_path')
    return path


def read_regular(root, relative):
    """Open each component without following symlinks; FIFO reads cannot block."""
    path = validate_path(relative)
    descriptor = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        for component in path.parts[:-1]:
            child = os.open(component, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child

        fd = os.open(path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=descriptor)
        try:
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                raise ValueError('package_input_not_regular')
            with os.fdopen(fd, 'rb', closefd=False) as stream:
                return stream.read()
        finally:
            os.close(fd)
    finally:
        os.close(descriptor)


def pattern_paths(root):
    paths = set()
    for pattern in PATTERNS:
        for candidate in root.glob(pattern):
            if candidate.is_symlink():
                raise ValueError('package_tree_symlink')
            if candidate.is_file():
                relative = candidate.relative_to(root).as_posix()
                validate_path(relative)
                paths.add(relative)
    return paths


def project_version(root):
    """Single release version; pyproject and master_ops.__version__ must agree."""
    project = read_regular(root, 'pyproject.toml').decode()
    section = re.search(r'^\[project\]\s*$(.*?)(?=^\[|\Z)', project, re.M | re.S)

    declared = re.search(r'^version\s*=\s*"([^"]+)"\s*$', section.group(1) if section else '', re.M)
    module = re.search(r"^__version__\s*=\s*['\"]([^'\"]+)['\"]\s*$",
                       read_regular(root, 'src/master_ops/__init__.py').decode(), re.M)
    if not declared or not module or declared.group(1) != module.group(1):
        raise ValueError('package_version_mismatch')
    return declared.group(1)


def source_paths(root):
    for relative in REQUIRED_FILES:
        if not (root / relative).is_file():
            raise FileNotFoundError(relative)
    paths = set(REQUIRED_FILES) | pattern_paths(root)
    for tree in TREES:
        base = root / tree
        if not stat.S_ISDIR(base.lstat().st_mode):
            raise ValueError('package_tree_not_directory')
        for current, dirs, files in os.walk(base, followlinks=False):
            for name in list(dirs):
                candidate = Path(current) / name
                if name.startswith('.') or name in BANNED:
                    dirs.remove(name)
                elif candidate.is_symlink():

                    raise ValueError('package_tree_symlink')
            for name in files:
                if name.endswith('.py'):
                    relative = (Path(current) / name).relative_to(root).as_posix()
                    validate_path(relative)
                    paths.add(relative)
    return sorted(paths - EXCLUDED)


