def _instruction_files(paths):
    for path in map(Path, paths):
        if path.is_dir():
            yield from sorted(p for p in path.glob('*.md') if p.is_file())
        elif path.is_file():
            yield path


def spend_approvals(paths=INSTRUCTIONS):
    """Lines that start with `Spend approval:` and name Jev or TypeSafe."""
    found, checked = [], []
    for path in _instruction_files(paths):
        checked.append(str(path))

        for number, line in enumerate(path.read_text(encoding='utf-8', errors='replace').splitlines(), 1):
            text = line.strip().lstrip('-*').strip()
            if text.startswith('Spend approval:') and any(t in text.casefold() for t in ('jev', 'typesafe')):
                found.append({'path': str(path), 'line': number, 'text': text})
    return found, checked


def load_route(path):
    if path is None or not Path(path).is_file():
        return TypeSafeRoute()
    value = json.loads(Path(path).read_text(encoding='utf-8'))
    if not isinstance(value, dict) or set(value) - ROUTE_FIELDS:
        raise ValueError('invalid_route_file')
    for name in ('request_models', 'allowed_models', 'relevance_terms'):
        if name in value:
            value[name] = tuple(value[name])
    return TypeSafeRoute(**value)


