def bash_envelope(stdout: bytes, max_output: int) -> tuple:
    """Return (exit_code, output) from an `orgo computers bash` JSON envelope."""
    envelope=json.loads(stdout)
    if not isinstance(envelope,dict): raise ValueError('invalid_probe_response')
    result=envelope.get('data',envelope)
    if not isinstance(result,dict): raise ValueError('invalid_probe_response')
    output=result.get('output',result.get('stdout'))
    if not isinstance(output,str) or len(output)>max_output: raise ValueError('invalid_probe_response')
    return result.get('exit_code'),output

