_OPAQUE = re.compile(r'[A-Za-z0-9+/_=-]{40,}')


def reject_secrets(value, path='$'):
    """Raise binding_secret_denied for credential-shaped keys or values anywhere."""
    if isinstance(value, dict):
        for key, item in value.items():
            if str(key).lower().replace('-', '_') in _SECRET_KEYS:
                raise BuildError('binding_secret_denied')
            reject_secrets(item, f'{path}.{key}')
    elif isinstance(value, list):
        for item in value:
            reject_secrets(item, path)
    elif isinstance(value, str):
        if any(p.search(value) for p in _SECRET_VALUES):
            raise BuildError('binding_secret_denied')

        # Mixed-case opaque runs look like keys; lowercase hex digests and UUIDs do not.
        for run in _OPAQUE.findall(value):
            if re.search('[A-Z]', run) and re.search('[a-z]', run) and re.search('[0-9]', run):
                raise BuildError('binding_secret_denied')


