def _read_json(path):
    fd = os.open(os.fspath(path), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        info = os.fstat(fd)

        if not stat.S_ISREG(info.st_mode) or info.st_size > 1_048_576:
            raise BuildError('regular_bindings_file_required')
        with os.fdopen(fd, 'r', encoding='utf-8') as stream:
            fd = None
            return json.load(stream)
    finally:
        if fd is not None:
            os.close(fd)


def parse_agent_bindings(document):
    """Validate a bindings document and return {agent_id: AgentBinding}."""
    _fields(document, {'schema', 'source_date', 'scope', 'sources', 'agents', 'reserved_capability_patterns'},
            {'schema', 'sources', 'agents'})
    if document['schema'] != SCHEMA_ID:
        raise BuildError('unsupported_bindings_schema')
    reject_secrets(document)
    reserved = document.get('reserved_capability_patterns', {})
    if not isinstance(reserved, dict) or not all(isinstance(k, str) and k and isinstance(v, str) and v.strip()
                                                 for k, v in reserved.items()):
        raise BuildError('invalid_reserved_capabilities')
    sources = document['sources']

    if not isinstance(sources, dict) or not sources or not isinstance(document['agents'], dict):
        raise BuildError('invalid_agent_binding')
    result = {}
    for agent_id, raw in document['agents'].items():
        if not isinstance(agent_id, str) or not _AGENT_ID.fullmatch(agent_id):
            raise BuildError('invalid_agent_id')
        result[agent_id] = _parse_agent(agent_id, raw, sources)
    return result


