roots = raw.get('roots', {})
if not isinstance(roots, dict) or not all(isinstance(v, str) for v in roots.values()):
    raise BuildError('invalid_agent_binding')
resources = raw.get('resources', [])
if not isinstance(resources, list):
    raise BuildError('invalid_agent_binding')
for item in resources:
    if not isinstance(item, dict):

            raise BuildError('invalid_agent_binding')
        _evidence(item, sources)
    return AgentBinding(agent_id, display, MappingProxyType(host), tuple(accounts), MappingProxyType(remote),
                        MappingProxyType(dict(roots)), fence['allowed_capabilities'], fence['effects'],
                        fence['command_recipes'], tuple(MappingProxyType(dict(r)) for r in resources),
                        MappingProxyType(unresolved), MappingProxyType(evidence))


def load_agent_bindings(path):
    """Load the trusted bindings file (no symlinks, regular file, <=1 MiB)."""
    return parse_agent_bindings(_read_json(path))


def reserved_capability_patterns(path):
    """{pattern: reason} for fence patterns intentionally ahead of any registered capability."""
    document = _read_json(path)
    parse_agent_bindings(document)
    return dict(document.get('reserved_capability_patterns', {}))


def agent_narrowing(binding, extra_accounts=None):
    """Keyword arguments for BuildProfile.derive / MasterBuildSDK.derive.

    extra_accounts ({provider: [account]}) carries host-configured labels for providers the
    binding leaves unresolved (for example the Orgo route); the master must already hold them.
    """
    accounts = {}
    for ref in binding.accounts:
        if ref.account:
            accounts.setdefault(ref.provider, []).append(ref.account)
    for provider, values in (extra_accounts or {}).items():
        for value in values:
            if value not in accounts.setdefault(provider, []):
                accounts[provider].append(value)
    return dict(allowed_capabilities=binding.allowed_capabilities, roots=dict(binding.roots),
                accounts={k: tuple(v) for k, v in accounts.items()}, effects=binding.effects,
                command_recipes=binding.command_recipes)


def agent_profile(master, binding, extra_accounts=None):
    """Derive the agent's BuildProfile from the master; any widening is agent_<code>."""
    try:
        return master.derive(binding.agent_id, **agent_narrowing(binding, extra_accounts))
    except BuildError:
        raise

    except ValueError as error:
        raise BuildError('agent_'+str(error)) from None


def agent_sdk(master_sdk, binding, extra_accounts=None):
    """Derived MasterBuildSDK sharing the master's ledger and registry.

    Without extra_accounts, accounts the master SDK assigned to this agent at configuration
    (for example its remote-file target account) are applied.
