def safe_output(text):
    """Credential projection extends the legacy sanitizer for quoted JSON and PEM."""
    import re
    from ..security import sanitize
    text=sanitize(text)
    text=re.sub(r'-----BEGIN (?:[A-Z ]*PRIVATE KEY)-----.*?(?:-----END [A-Z ]*PRIVATE KEY-----|$)', '[REDACTED]', text, flags=re.S)
    text=re.sub(r'(?i)([\"\'](?:password|passwd|secret|token|credential|authorization|api[_-]?key|private[_-]?key|cookie)[\"\']\s*:\s*)[\"\'][^\"\']*[\"\']', r'\1"[REDACTED]"', text)
    try:
        value=json.loads(text)
        projected=sanitize(value)
        if projected!=value: return json.dumps(projected,sort_keys=True)
    except (ValueError,TypeError): pass
    return text


def safe_result(value):
    """Project secrets, preserving only typed provider accounting and null errors.

Token counters are allowed only inside a structured usage object and only
when their value is a nonnegative integer or null. Strings still redact.
"""
from ..security import sanitize
usage_keys = {'input_tokens', 'output_tokens', 'total_tokens', 'prompt_tokens',
              'completion_tokens', 'cached_tokens', 'reasoning_tokens'}

def project(item, parent=None):
    if isinstance(item, str):
        return safe_output(item)
    if isinstance(item, dict):
        result = {}
        for key, value in item.items():
            key = str(key)
            counter = parent == 'usage' and key in usage_keys and (
                value is None or (isinstance(value, int) and not isinstance(value, bool) and value >= 0))
            if counter or (key == 'error' and value is None):
                result[key] = value
            elif sanitize({key: None})[key] == '[REDACTED]':
                result[key] = '[REDACTED]'
            else:
                result[key] = project(value, key)

        return result
    if isinstance(item, (list, tuple)):
        return [project(v, parent) for v in item]
    return sanitize(item)

