def unresolved_typesafe_capability(route):

    """Registered stand-in for an incomplete route: refuses with its first *_unresolved code, no calls."""
    missing = route.unresolved()
    if not missing:
        raise ValueError('typesafe_route_resolved')

    def handler(ctx, args):
