"""Cross-process serialization for owned build effects, separate from SQLite."""
from contextlib import contextmanager
import os
import stat
from .contracts import BuildError


@contextmanager
def build_lock(root):
    # No queued intent is written until this lock is held. A busy caller can
    # retry the same operation ID because it has not dispatched any effect.
    if os.name != 'posix':
        raise BuildError('build_lock_platform_unsupported')
    import fcntl
    fd = os.open(root / 'build.lock', os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW | os.O_NONBLOCK, 0o600)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise BuildError('build_lock_not_regular')
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise BuildError('build_busy') from None
        try:
            yield
        finally:
            fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)

