    response proves no effect; all other remote errors stay UNKNOWN.
    """
    def __init__(self, executable, artifact_root=None, timeout=90):
        self._executable = Path(executable)

    if not self._executable.is_absolute(): raise ValueError('absolute_executable_required')
    self.artifact_root = artifact_root
    self.timeout = timeout
    self._receipts = threading.local()

@property
