@last_receipt.setter
def last_receipt(self, value): self._receipts.value = copy.deepcopy(value)

def _run(self, arguments):
    process = run_bounded([str(self._executable), *arguments],
        timeout=self.timeout, max_output_bytes=8_388_608, capture_stderr=False)
    if process.returncode: raise ValueError('composio_process_failed')
    value = json.loads(process.stdout)
    if not isinstance(value, (dict, list)): raise ValueError('invalid_cli_response')
