class CloudDeliveryPublisher:
    """Knowledge publisher: explicit bindings, separate reader and writer, durable receipts.

    reader: metadata(account, user, file_id) -> (dict, log_id) and
            media(account, user, file_id) -> (bytes, kind, log_id).
    writer: write(destination, path, sha256) -> {'id': ..., ...} (a claim only).
    """
    def __init__(self, bindings, reader, writer, state_dir, recover_media=None):
        if reader is None or writer is None: raise DeliveryError('delivery_route_missing')
        if reader is writer: raise DeliveryError('independent_reader_required')
        bindings = list(bindings or [])
        if not bindings or not all(isinstance(b, DriveDestination) for b in bindings): raise DeliveryError('missing_destination_binding')
        self.bindings = {}
