class CapabilityRegistry:
    def __init__(self): self._capabilities={}
    def register(self,capability):
        if capability.capability_id in self._capabilities: raise ValueError('duplicate_capability')
        # Snapshot mutable schema independently of caller-owned object.
        self._capabilities[capability.capability_id]=Capability(capability.capability_id,capability.description,capability.input_schema,capability.effects,capability.handler,capability.revision)
        return self
    def get(self,name):
        if name not in self._capabilities: raise BuildError('capability_missing')
        c=self._capabilities[name]
        return Capability(c.capability_id,c.description,c.input_schema,c.effects,c.handler,c.revision)
    def list(self,profile=None):
        result=[]
        for name in sorted(self._capabilities):
            if profile:
                try: profile.check_capability(name)
                except BuildError: continue

        result.append(self.describe(name))
    return result
def search(self,query,profile=None):
    words=query.lower().split()
    matches=[]
    for name,capability in sorted(self._capabilities.items()):
        if not all(word in (name+' '+capability.description).lower() for word in words): continue
        if profile:
            try: profile.check_capability(name)
            except BuildError: continue
        matches.append(self.describe(name))
    return matches
def describe(self,name): return self.get(name).describe()
def invoke(self,executor,capability_id,arguments,operation_id,authority=None):
    return executor.invoke(capability_id,arguments,operation_id,authority)

