def _write(self, path, value):
    temp = path.with_name(path.name + '.tmp')
    fd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, 'w', encoding='utf-8') as stream:
        json.dump(value, stream, allow_nan=False)
    os.replace(temp, path)

def heartbeat(self):
    self._write(self.root / HOST_RECORD, {'host_id': self.host_id, 'heartbeat_at': time.time(),
                                          'meta_tools': sorted(self.allowed)})

def withdraw(self):
    try:
        (self.root / HOST_RECORD).unlink()
    except FileNotFoundError:
        pass

def pending(self):
    found = []
    for entry in sorted(self.root.iterdir()):
        if entry.is_symlink() or not entry.is_dir() or not _REQUEST_ID.fullmatch(entry.name):
            continue

        if (entry / 'request.json').exists() and not (entry / 'response.json').exists():
            found.append(entry)
    return found

def _request(self, directory):
    value, _ = read_regular_json(directory / 'request.json', self.root, 1_048_576)
    if not isinstance(value, dict) or set(value) != {'request_id', 'tool', 'arguments'}:
        raise ValueError('invalid_relay_request')
    if value['request_id'] != directory.name or not isinstance(value['arguments'], dict):
        raise ValueError('invalid_relay_request')
    if value['tool'] not in self.allowed:
        raise ValueError('unapproved_meta_tool')
    return value

def serve_pending(self):
    """Answer every pending request once; return how many were answered."""
    count = 0
    for directory in self.pending():
        try:
            request = self._request(directory)
        except Exception as error:
            self.rejected.append((directory.name, str(error)))
            continue
        try:

            result = self.meta_call(request['tool'], request['arguments'])
            json.dumps(result, allow_nan=False)
        except Exception:
            result = {'isError': True, 'content': [{'type': 'text', 'text': 'host_call_failed'}]}
        self._write(directory / 'response.json',
                    {'request_id': request['request_id'], 'tool': request['tool'], 'result': result})
        self.served.append((request['request_id'], request['tool']))
        count += 1
    return count

def serve_forever(self, stop, interval=0.05, heartbeat_every=10):
    """Serve until `stop` (threading.Event) is set; heartbeat stays fresh meanwhile."""
    last = 0.0
    try:
        while not stop.is_set():
            if time.monotonic() - last >= heartbeat_every:
                self.heartbeat()
                last = time.monotonic()
            self.serve_pending()
            stop.wait(interval)
    finally:
        self.withdraw()

