HELPER_B64 = base64.b64encode(HELPER.encode()).decode('ascii')


def build_command(request):
    """Fixed launcher; only base64 text is interpolated."""
    payload = base64.b64encode(json.dumps(request, sort_keys=True).encode()).decode('ascii')
    if not BASE64.fullmatch(HELPER_B64) or not BASE64.fullmatch(payload): raise BuildError('unsafe_command')
    return "python3 -c 'import base64,sys;exec(base64.b64decode(\"%s\"))' %s" % (HELPER_B64, payload)


def parse_helper_output(output):
    lines = [line for line in output.splitlines() if line.startswith(MARKER)]
    if len(lines) != 1: raise BuildError('invalid_remote_response')
    try: result = json.loads(lines[0][len(MARKER):])
    except ValueError: raise BuildError('invalid_remote_response') from None
    if not isinstance(result, dict) or not isinstance(result.get('ok'), bool): raise BuildError('invalid_remote_response')
    return result


