def owned_remote_path(path):
    if not isinstance(path, str) or not path.startswith('/') or '\x00' in path: raise BuildError('path_denied')
    if posixpath.normpath(path) != path or '..' in path.split('/') or path == '/': raise BuildError('path_denied')
    if any(secret_component(part) for part in path.split('/') if part): raise BuildError('secret_path_denied')
    return path


