class RemoteFiles:
    def __init__(self, transport, bindings):
        transports = transport if isinstance(transport, dict) else {transport.provider: transport}
        self.transports = MappingProxyType(dict(transports))
        self.bindings = normalize_bindings(bindings)

    def resolve(self, ctx, args, write=False):
        binding = self.bindings.get(args['target'])
        if binding is None: raise BuildError('target_denied')
        if args['agent_id'] != binding['agent_id']: raise BuildError('agent_target_mismatch')

    if ctx.profile.agent_id not in (binding['agent_id'], *binding['operator_agents']): raise BuildError('agent_denied')
    if args['computer_id'] != binding['computer_id']: raise BuildError('computer_mismatch')
    ctx.check_account(binding['provider'], binding['account'])
    transport = self.transports.get(binding['provider'])
    if transport is None: raise BuildError('provider_route_missing')
    if getattr(transport, 'account', None) != binding['account']: raise BuildError('account_route_mismatch')
    path = owned_remote_path(args['path'])
    def inside(roots): return any(path != root and posixpath.commonpath([root, path]) == root for root in roots)
    if not inside(binding['owned_paths']):
        if not inside(binding['read_paths']): raise BuildError('path_outside_owned')
        if write: raise BuildError('remote_write_denied')
    return binding, transport, path

@staticmethod
def roots(binding, op):
    return list(binding['owned_paths']) + ([] if op == 'write' else list(binding['read_paths']))

def call(self, binding, transport, path, op, **fields):
    result = transport.run(binding['computer_id'], dict(op=op, path=path, roots=self.roots(binding, op), **fields))
    if binding['hostname'] and result.get('hostname') != binding['hostname']: raise BuildError('host_identity_mismatch')
    return result

def inspect(self, binding, transport, path, content=False):
    result = self.call(binding, transport, path, 'inspect', content=content)
    if not result['ok']: raise BuildError(str(result.get('code', 'remote_inspect_failed')))
    data = None
    if content and result.get('exists'):
        try: data = base64.b64decode(result.get('content_b64', ''), validate=True)
        except (ValueError, TypeError): raise BuildError('invalid_remote_response') from None
        if digest(data) != result.get('digest'): raise BuildError('remote_digest_mismatch')
        text = data.decode('utf-8', errors='replace')
        if safe_output(text) != text: raise BuildError('secret_content_denied')
    return result, data

