def _classify(error, denied, default, blocked=()):
    if blocked:
        return blocked[0]
    if denied:
        return "connect_authentication_failed"
    leaves = list(_leaves(error))
    for leaf in leaves:
        if isinstance(leaf, _Failure):
            return leaf.code
    for leaf in leaves:
        if isinstance(leaf, httpx2.HTTPStatusError) and leaf.response.status_code in (401, 403):
            return "connect_authentication_failed"
    for leaf in leaves:
        if isinstance(leaf, TimeoutError) or (isinstance(leaf, MCPError) and leaf.code == REQUEST_TIMEOUT):
            return "host_response_timeout"
    return default(leaves)


