def _group_failure(error):
    """Only exception classes/static codes survive SDK context unwind groups."""
    if isinstance(error, BaseExceptionGroup):

        codes = [_group_failure(child) for child in error.exceptions]
        for preferred in (("timeout", "transport_error"), ("invalid_result", "protocol_error"),
                          ("mcp_protocol_error", "protocol_error")):
            if preferred in codes:
                return preferred
    elif isinstance(error, (TimeoutError, MCPError)):
        if isinstance(error, TimeoutError) or error.code == types.REQUEST_TIMEOUT:
            return "timeout", "transport_error"
        if error.code != types.CONNECTION_CLOSED:
            return "mcp_protocol_error", "protocol_error"
    elif isinstance(error, ProtocolValidationError):
        return "invalid_result", "protocol_error"
    return "transport_failure", "transport_error"


