@staticmethod
def _open(source):
    """Walk from / through no-follow directory descriptors, including the root."""
    path, root = Path(source['path']), Path(source['root'])
    if '..' in path.parts or '..' in root.parts or any(p.startswith('.env') for p in path.parts):
        raise ValueError('unsafe_source')
    try:
        path.relative_to(root)
    except ValueError:
        raise ValueError('unsafe_source') from None
    fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY)

    try:
        for component in path.parts[1:-1]:
            next_fd = os.open(component, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            os.close(fd)
            fd = next_fd
        final = os.open(path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=fd)
    except OSError as exc:
        # No provider error/path details escape the boundary.
        if exc.errno in (20, 40, 62):
            raise ValueError('unsafe_source') from None
        raise ValueError('source_unavailable') from None
    finally:
        os.close(fd)
    info = os.fstat(final)
    if not stat.S_ISREG(info.st_mode):
        os.close(final)
        raise ValueError('unsafe_source')
    return final, info

