            age = (datetime.now(timezone.utc) - parsed).total_seconds()
            evidence = 'future_date' if age < 0 else 'historical_date_not_revalidated'
        except (ValueError, OverflowError):
            evidence = 'invalid_date'
    return dict(file='current_file_revision', evidence=evidence, evidence_age_seconds=age)

