class Ledger:
    def __init__(self,state_dir):
        self.root=Path(state_dir);self.root.mkdir(parents=True,exist_ok=True)
        self.path=self.root/'ledger.sqlite3'
        with self.connect() as db:
            db.executescript('''CREATE TABLE IF NOT EXISTS proposals(proposal_id TEXT PRIMARY KEY,body TEXT NOT NULL,digest TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS reviews(proposal_id TEXT PRIMARY KEY,digest TEXT NOT NULL,body TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS runs(run_id TEXT PRIMARY KEY,proposal_id TEXT UNIQUE NOT NULL,body TEXT NOT NULL,lease_owner TEXT);
            CREATE TABLE IF NOT EXISTS checkpoints(run_id TEXT NOT NULL,sequence INTEGER NOT NULL,body TEXT NOT NULL,PRIMARY KEY(run_id,sequence));''')
    def connect(self): return sqlite3.connect(self.path,timeout=10)

def save_proposal(self,p):
    with self.connect() as db: db.execute('INSERT INTO proposals VALUES(?,?,?)',(p['proposal_id'],json.dumps(p,sort_keys=True),p['digest']))
def proposal(self,pid):
    with self.connect() as db: row=db.execute('SELECT body,digest FROM proposals WHERE proposal_id=?',(pid,)).fetchone()
    if not row: raise ValueError('proposal_missing')
    p=json.loads(row[0]);digest=p.pop('digest',None);actual=fingerprint(p);p['digest']=digest
    if digest!=actual or digest!=row[1]: raise ValueError('proposal_tampered')
    return p
def review(self,pid,body):
    with self.connect() as db: db.execute('INSERT OR REPLACE INTO reviews VALUES(?,?,?)',(pid,body['digest'],json.dumps(body,sort_keys=True)))
def reviewed(self,p):
    with self.connect() as db: row=db.execute('SELECT digest,body FROM reviews WHERE proposal_id=?',(p['proposal_id'],)).fetchone()
    if not row or row[0]!=p['digest']: return False
    r=json.loads(row[1]);a=r.get('authorization',{})

    return a.get('digest')==p['digest'] and a.get('target')==p['target'] and a.get('scope')=='sdk_owned_local_file' and bool(r.get('reviewer')) and bool(a.get('evidence'))
def run(self,p):
    with self.connect() as db:
        db.execute('BEGIN IMMEDIATE')
        row=db.execute('SELECT body FROM runs WHERE proposal_id=?',(p['proposal_id'],)).fetchone()
        if row: return json.loads(row[0])
        now=utc_now();r=dict(run_id=str(uuid.uuid4()),proposal_id=p['proposal_id'],target_id=p['target']['target_id'],state='NOT_PROVEN',summary='Run ready',checkpoints=[],evidence=[],limitations=[],proof_level='tested_locally',created_at=now,updated_at=now,contract_version=CONTRACT_VERSION)
        db.execute('INSERT INTO runs VALUES(?,?,?,NULL)',(r['run_id'],p['proposal_id'],json.dumps(r)))
        return r
