    if not isinstance(value, str) or not value.strip() or len(value) > limit or sanitize(value) != value:
        raise ValueError('invalid_memory_text')
    for url in re.findall(r'https?://[^\s<>]+', value):
        try:
            parts = urlsplit(url)
            if parts.username or parts.password or any(re.search(r'(?i)token|key|secret|credential|signature|authorization|password', k) for k, _ in parse_qsl(parts.query)):
                raise ValueError('invalid_memory_text')
        except ValueError: raise ValueError('invalid_memory_text') from None
    return value


def _sha(text):
    return hashlib.sha256(text.encode('utf-8')).hexdigest()


