                'unsupported_service'}
_OUTCOMES = {'returned', 'tool_error', 'protocol_error', 'transport_error', 'rejected'}
_INCOMPLETE = {'partial', 'unavailable', 'unknown', 'not_proven', 'blocked', 'missing', 'truncated', 'stale', 'failed', 'error'}


def _thread(value):
    if not isinstance(value, str): return False
    try: return str(uuid.UUID(value)) == value.lower()
    except ValueError: return False


def _bounded(value, depth=0):
    """Return ephemeral sanitized data while retaining nested domain signals."""
    if depth > 16: return {'truncated': True, 'limitation': 'operation_result_depth'}
    if isinstance(value, dict):
        result = {str(k)[:128]: _bounded(v, depth + 1) for k, v in list(value.items())[:200]}
        if len(value) > 200: result['truncated'] = True
        return result
    if isinstance(value, (list, tuple)):
        result = [_bounded(v, depth + 1) for v in value[:200]]
        if len(value) > 200: result.append({'truncated': True})

        return result
    if isinstance(value, str):
        # The marker itself is handled as incomplete evidence by _partial.
        return value if len(value) <= 12000 else value[:12000] + '\n[operation_result_truncated]'
    if isinstance(value, float) and not math.isfinite(value): return '[UNSUPPORTED]'
    return value


def _partial(value):
    if isinstance(value, dict):
        for key, child in value.items():
            if key.lower() in {'truncated', 'partial', 'unavailable'} and child is True: return True
            if key.lower() in {'ok', 'available', 'complete'} and child is False: return True
            if key.lower() in {'state', 'status', 'completeness', 'freshness', 'evidence_state', 'evidence_status', 'file'} and isinstance(child, str) and child.lower() in _INCOMPLETE: return True
            if _partial(child): return True
    elif isinstance(value, list): return any(_partial(v) for v in value)
    elif isinstance(value, str): return '[operation_result_truncated]' in value
    return False


def _upstream(value):

    """Persist only explicitly typed, bounded identifiers, never upstream prose."""
    result = {}
    def visit(node):
        if isinstance(node, dict):
            for key, child in node.items():
                if key in _ID_KEYS and isinstance(child, str) and _POINTER.fullmatch(child) and sanitize(child) == child:
                    result.setdefault(key, child)
                elif isinstance(child, (dict, list)): visit(child)
        elif isinstance(node, list):
            for child in node: visit(child)
    visit(value)
    return result


class OperationService:
    def __init__(self, ledger, integrations, catalog, knowledge):
        self.ledger = ledger
        self.integrations = integrations
        self.catalog = catalog
        self.knowledge = knowledge
        with closing(ledger.connect()) as db, db:
            db.executescript('''CREATE TABLE IF NOT EXISTS operations(
                operation_id TEXT PRIMARY KEY, capability_id TEXT NOT NULL,
                request_digest TEXT NOT NULL, body TEXT NOT NULL);

            CREATE TABLE IF NOT EXISTS operation_steps(
            parent_operation_id TEXT NOT NULL, step_key TEXT NOT NULL,
            child_operation_id TEXT NOT NULL,
            PRIMARY KEY(parent_operation_id,step_key));''')

def _identifier(self, operation_id):
    if operation_id is None: return str(uuid.uuid4())
    if not isinstance(operation_id, str) or not _ID.fullmatch(operation_id) or sanitize(operation_id) != operation_id:
        raise ValueError('invalid_operation_id')
    return operation_id

def _digest(self, capability_id, arguments, authorization=None):
    if not isinstance(capability_id, str) or not re.fullmatch(r'(?:sdk|bridge|observatory|knowledge|workflow)\.[a-z_]{1,64}', capability_id) or not isinstance(arguments, dict):
        raise ValueError('invalid_operation_request')
    try:
        return fingerprint({'capability_id': capability_id, 'arguments': arguments,
                            'authority': authorization})

def get(self, operation_id):
    operation_id = self._identifier(operation_id)
    with closing(self.ledger.connect()) as db, db:
        row = db.execute('SELECT body FROM operations WHERE operation_id=?', (operation_id,)).fetchone()
    if not row: raise ValueError('operation_missing')
    receipt = json.loads(row[0])
    with closing(self.ledger.connect()) as db, db:
        steps = db.execute('''SELECT s.child_operation_id,o.body FROM operation_steps s
            LEFT JOIN operations o ON o.operation_id=s.child_operation_id
            WHERE s.parent_operation_id=? ORDER BY s.step_key''', (operation_id,)).fetchall()
        if steps:
            receipt['steps'] = [step[0] for step in steps]
            for child_id, body in steps:
                if body:
                    for key, value in json.loads(body).get('upstream_ids', {}).items():
                        receipt['upstream_ids'].setdefault(key, value)
    return self._historical(receipt)

def _reject(self, receipt, code, native=False):

    receipt.update(state='BLOCKED', status='rejected', summary='Use the native SDK API for this capability' if native else 'Operation rejected: ' + code,
                   limitations=[code])
    return self._save(receipt)

