    character bounds are additional limits, never a substitute for the content hash."""
    from .build.recall import CONTEXT_FOOTER, CONTEXT_HEADER
    if (not isinstance(approval, dict) or set(approval) != {'max_items', 'max_chars', 'sha256'}
