class FakeReader:
    def __init__(self, drive, media_kind='decoded_text', before_media=None):
        self.drive, self.calls, self.media_kind, self.before_media = drive, [], media_kind, before_media
    def metadata(self, account, user, file_id):
        self.calls.append(('metadata', account, user, file_id))
        if account != ACCOUNT or user != USER: raise ValueError('route_identity_mismatch')
        item = self.drive.files[file_id]
        meta = {k: v for k, v in item.items() if k != 'data'}
        meta.update(size=str(len(item['data'])), sha256Checksum=sha(item['data']))

        return meta, 'log-%d' % len(self.calls)
    def media(self, account, user, file_id):
        self.calls.append(('media', account, user, file_id))
        if self.before_media: self.before_media(file_id)
        raw = self.drive.files[file_id]['data']
        if self.media_kind == 'latin1':
            raw = raw.decode('latin-1').encode('utf-8')
        return raw, 'decoded_text', 'log-%d' % len(self.calls)


class FakeWriter:
    def __init__(self, drive, corrupt=False, fail=False):
        self.drive, self.calls, self.corrupt, self.fail = drive, [], corrupt, fail
    def write(self, destination, path, sha256):
        self.calls.append((destination.source_id, destination.account, destination.file_id, sha256))
        if self.fail: raise RuntimeError('network dropped SECRET')
        data = Path(path).read_bytes()
        if destination.file_id is None:
            file_id = 'created_%d' % len(self.calls)
            self.drive.add(file_id, destination.name, b'corrupted' if self.corrupt else data, destination.mime_type, destination.folder_id)
        else:

            file_id = destination.file_id
            self.drive.store(file_id, b'corrupted' if self.corrupt else data)
        # The write response always claims success with the intended digest.
