class SpyEnviron(dict):
    """os.environ stand-in that records reads of the watched names and any bulk read."""
    def __init__(self, base, watch):
        super().__init__(base)
        self.watch, self.reads = frozenset(watch), []

    def _note(self, key):
        if key in self.watch:
            self.reads.append(key)

    def __getitem__(self, key):
        self._note(key)
        return super().__getitem__(key)

    def get(self, key, default=None):

        self._note(key)
        return super().get(key, default)

    def __contains__(self, key):
        self._note(key)
        return super().__contains__(key)

    def _bulk(self):
        self.reads.append('*')

    def __iter__(self):
        self._bulk(); return super().__iter__()

    def items(self):
        self._bulk(); return super().items()

    def values(self):
        self._bulk(); return super().values()

    def copy(self):
        self._bulk(); return dict(self)


