class Repair:
    repair_id='fixture'; version='1'
    def __init__(self): self.writes=0; self.fail=False; self.enter=None; self.release=None
    def inspect(self,t):
        observed=json.loads(Path(t.resource).read_text())
        return Inspection(t.target_id,'VERIFIED',fingerprint(observed),'Safe fixture',observed=observed,identity_verified=True)
    def propose(self,t,i):
        return dict(observed=i.observed,intended={'version':1},preconditions=i.observed,changes={'version':1},authorization_requirements=['sdk_owned_local_file'],recovery={'backup':True},verification_criteria=['version equals one'])
    def apply(self,t,p,checkpoint):
        if self.enter: self.enter.set(); self.release.wait(5)
        path=Path(t.resource); old=path.read_bytes(); new=b'{"version": 1}'; backup=path.with_suffix('.backup'); backup.write_bytes(old)

        checkpoint(dict(phase='intent',path=str(path),backup_path=str(backup),preimage_digest=hashlib.sha256(old).hexdigest(),postimage_digest=hashlib.sha256(new).hexdigest()))
        path.write_bytes(new);self.writes+=1
        if self.fail: raise RuntimeError('api_key=TOPSECRET_TOKEN password=hunter2')
        checkpoint(dict(phase='postimage',postimage_digest=hashlib.sha256(new).hexdigest()))
        return {'summary':'Applied fixture'}
    def verify(self,t,r): return self.inspect(t)

