    if not any(request['path'].startswith(root + '/') for root in request['roots']):
        return dict(ok=False, code='path_outside_owned', hostname=self.hostname)
    if request['op'] == 'inspect':
        if data is None:
            return dict(ok=True, exists=False, hostname=self.hostname)
        info = dict(ok=True, exists=True, bytes=len(data), digest=sha, mode=0o600, uid=1000, gid=1000, hostname=self.hostname)
        if request.get('content'):
            info['content_b64'] = base64.b64encode(data).decode()
        return info
    if sha != request['expected']:

            return dict(ok=False, code='stale_revision', digest=sha, hostname=self.hostname)
        if request['content_b64'] is None:
            del self.files[key]
            return dict(ok=True, written=True, bytes=0, hostname=self.hostname)
        self.files[key] = base64.b64decode(request['content_b64'])
        return dict(ok=True, written=True, bytes=len(self.files[key]), hostname=self.hostname)


