class SpoolHarness:
    kind = 'spool'

    def __init__(self, root, script, timeout, mode='serve'):
        self.spool, self.script, self.timeout, self.mode = root/'spool', script, timeout, mode
        self.client = self.thread = None

    def __enter__(self):
        allowed = META_TOOLS - {'COMPOSIO_GET_TOOL_SCHEMAS'} if self.mode == 'missing_tool' else META_TOOLS
        self.host = SpoolRelayHost(self.spool, self.script, 'contract-native-host', allowed_tools=allowed)
        if self.mode in ('serve', 'missing_tool'):
            self.thread, self.stop = self.host.start(interval=0.01)
        elif self.mode == 'unserviced':
            self.host.heartbeat()
        elif self.mode == 'stale':
            self.host.heartbeat()
            record = json.loads((self.spool/HOST_RECORD).read_text()); record['heartbeat_at'] -= 600

            (self.spool/HOST_RECORD).write_text(json.dumps(record))
        return self

    def open(self):
        self.client = SpoolMetaClient(self.spool, timeout=self.timeout, require_host=True, max_host_age=60)
        return self.client

    def meta_tool_calls(self):
        return [tool for _, tool in self.host.served]

    def requests_written(self):
        return [p.name for p in self.spool.iterdir() if p.name != HOST_RECORD]

    def __exit__(self, *exc):
        if self.thread:
            self.stop.set(); self.thread.join(5)


class ConnectHarness:
    kind = 'connect'

    def __init__(self, cls, script, timeout, tools=CONNECT_TOOLS, key=FAKE_KEY, expected_key=FAKE_KEY,
                 auth_status=None, page_size=4):
        self.cls, self.script, self.timeout, self.key = cls, script, timeout, key
        self.server = ConnectFakeServer(script, tools=tools, expected_key=expected_key, auth_status=auth_status,
                                        page_size=page_size)
        self.client = None

    def __enter__(self):
        self.server.start()

        if self.key is None:
            os.environ.pop(KEY_ENV, None)
        else:
            os.environ[KEY_ENV] = self.key
        return self

    def open(self):
        # The approved URL only; the injected transport carries it to the loopback fake.
        self.client = self.cls(CONNECT_URL, credential_env=KEY_ENV, timeout=self.timeout, startup_timeout=5,
                               transport_factory=self.server.transport_factory())
        return self.client

    def meta_tool_calls(self):
        return [name for name, _ in self.server.tool_calls]

    def requests_written(self):
        return self.meta_tool_calls()

    def __exit__(self, *exc):
        try:
            if self.client is not None:
                self.client.close()
        finally:
            self.server.stop()


