            skills = self.skills if self.skills is not None else [{'id': 'sk-doc', 'slug': 'doc-metadata', 'title': 'Google document metadata'}]
            return {'structuredContent': {'skills': skills}, 'isError': False}
        if tool == 'COMPOSIO_USE_SKILL':
            return {'structuredContent': {'id': 'sk-doc', 'slug': 'doc-metadata'}, 'content': [{'type': 'text', 'text': self.content}]}
        if tool == 'COMPOSIO_SEARCH_TOOLS':
            value = {'successful': True, 'data': {'results': [{'primary_tool_slugs': [SLUG]}], 'session': {'id': 'sess'}}}
        else:
            value = {'successful': True, 'data': {'tool_schemas': {SLUG: {'input_schema': SCHEMA}}}}
        return {'content': [{'type': 'text', 'text': json.dumps(value)}]}


